#include <string>
#include <unordered_set>
#include <vector>

// 1
long sum(const std::vector<int>& v) {
  long s = 0;
  for (int x : v) s += x;
  return s;
}

// 2
bool has_duplicate_pairwise(const std::vector<int>& v) {
  for (std::size_t i = 0; i < v.size(); ++i)
    for (std::size_t j = i + 1; j < v.size(); ++j)
      if (v[i] == v[j]) return true;
  return false;
}

// 3
int halvings(int n) {
  int steps = 0;
  while (n > 1) {
    n /= 2;
    ++steps;
  }
  return steps;
}

// 4
bool has_duplicate_hashed(const std::vector<int>& v) {
  std::unordered_set<int> seen;
  for (int x : v)
    if (!seen.insert(x).second) return true;
  return false;
}

// 5
std::string repeat(const std::string& s, int k) {
  std::string out;
  for (int i = 0; i < k; ++i) out += s;
  return out;
}

int main() {
  std::vector<int> v{3, 1, 4, 1, 5};
  bool ok = sum(v) == 14 && has_duplicate_pairwise(v) && halvings(8) == 3 && has_duplicate_hashed(v) &&
            repeat("ab", 3) == "ababab";
  return ok ? 0 : 1;
}

