#include <cstdio>

int main() {
  const int n = 1024;
  long nested = 0, doubling = 0;
  for (int i = 0; i < n; ++i)      // the inner loop runs i times
    for (int j = 0; j < i; ++j) ++nested;
  for (int i = 1; i < n; i *= 2)   // the inner loop also runs i times, but i doubles
    for (int j = 0; j < i; ++j) ++doubling;
  std::printf("nested: %ld steps, doubling: %ld steps\n", nested, doubling);
}

#include <chrono>
#include <cstdio>
#include <numeric>
#include <unordered_set>
#include <vector>

bool has_duplicate_pairwise(const std::vector<int>& v) {
  for (std::size_t i = 0; i < v.size(); ++i)
    for (std::size_t j = i + 1; j < v.size(); ++j)
      if (v[i] == v[j]) return true;
  return false;
}

bool has_duplicate_hashed(const std::vector<int>& v) {
  std::unordered_set<int> seen;
  for (int x : v)
    if (!seen.insert(x).second) return true;
  return false;
}

template <class F>
double millis(F f, const std::vector<int>& v) {
  auto start = std::chrono::steady_clock::now();
  volatile bool found = f(v);  // volatile: the optimiser must not skip the call
  (void)found;
  return std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - start).count();
}

int main() {
  for (int n = 1000; n <= 8000; n *= 2) {
    std::vector<int> v(n);
    std::iota(v.begin(), v.end(), 0);  // 0, 1, 2, ...: no duplicates, the worst case
    std::printf("n = %5d  pairwise %8.2f ms  hashed %6.2f ms\n", n, millis(has_duplicate_pairwise, v),
                millis(has_duplicate_hashed, v));
  }
}

#include <cstdio>
#include <vector>

struct Counted {
  static inline int moves = 0;
  int value;
  explicit Counted(int v) : value(v) {}
  Counted(Counted&& other) noexcept : value(other.value) { ++moves; }
};

int main() {
  std::vector<Counted> v;
  std::size_t last = v.capacity();
  for (int i = 1; i <= 20; ++i) {
    v.emplace_back(i);
    if (v.capacity() != last) {
      last = v.capacity();
      std::printf("size %2zu -> capacity %zu\n", v.size(), last);
    }
  }
  std::printf("20 pushes moved %d elements in total\n", Counted::moves);
}

#include <cstdio>
#include <vector>

struct Counted {
  static inline int moves = 0;
  static inline int copies = 0;
  int value;
  explicit Counted(int v) : value(v) {}
  Counted(const Counted& other) : value(other.value) { ++copies; }
  Counted(Counted&& other) : value(other.value) { ++moves; }  // not noexcept
};

int main() {
  std::vector<Counted> v;
  for (int i = 1; i <= 20; ++i) v.emplace_back(i);
  std::printf("moves %d, copies %d\n", Counted::moves, Counted::copies);
}
